import "package:flutter/material.dart"; import "package:cached_network_image/cached_network_image.dart"; import "package:carousel_slider/carousel_slider.dart"; import "../models/property.dart"; class PropertyDetailScreen extends StatelessWidget { final String id; const PropertyDetailScreen({super.key, required this.id}); @override Widget build(BuildContext context) { return Scaffold(appBar: AppBar(title: const Text("Property Details"), backgroundColor: Colors.blue), body: FutureBuilder<Property>(future: _loadProperty(), builder: (context, snapshot) { if (snapshot.connectionState == ConnectionState.waiting) { return const Center(child: CircularProgressIndicator()); } if (snapshot.hasError) { return Center(child: Text("Error: \${snapshot.error}")); } if (!snapshot.hasData) { return const Center(child: Text("Property not found")); } final property = snapshot.data!; return SingleChildScrollView(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [if (property.images.isNotEmpty) CarouselSlider(items: property.images.map((imageUrl) => CachedNetworkImage(imageUrl: imageUrl, fit: BoxFit.cover, placeholder: (context, url) => const Center(child: CircularProgressIndicator()), errorWidget: (context, url, error) => const Icon(Icons.error))).toList(), options: CarouselOptions(height: 250, viewportFraction: 1.0, autoPlay: true)), Padding(padding: const EdgeInsets.all(16.0), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(property.title, style: const TextStyle(fontSize: 24, fontWeight: FontWeight.bold)), const SizedBox(height: 8), Text("\$${property.price.toStringAsFixed(0)}", style: const TextStyle(fontSize: 20, color: Colors.green, fontWeight: FontWeight.bold)), const SizedBox(height: 16), Row(children: [Icon(Icons.location_on, color: Colors.grey), const SizedBox(width: 8), Expanded(child: Text("\${property.address}, \${property.city}, \${property.state} \${property.zipcode}", style: const TextStyle(fontSize: 16, color: Colors.grey)))],), const SizedBox(height: 16), Row(children: [Expanded(child: _buildInfoCard("Bedrooms", property.bedrooms.toString(), Icons.bed)), const SizedBox(width: 16), Expanded(child: _buildInfoCard("Bathrooms", property.bathrooms.toString(), Icons.bathroom)), const SizedBox(width: 16), Expanded(child: _buildInfoCard("Area", "\${property.area} sq ft", Icons.square_foot))]), const SizedBox(height: 16), Row(children: [Container(padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6), decoration: BoxDecoration(color: Colors.blue, borderRadius: BorderRadius.circular(20)), child: Text(property.type, style: const TextStyle(color: Colors.white, fontWeight: FontWeight.bold))), const SizedBox(width: 12), Container(padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6), decoration: BoxDecoration(color: property.status == "For Sale" ? Colors.green : Colors.orange, borderRadius: BorderRadius.circular(20)), child: Text(property.status, style: const TextStyle(color: Colors.white, fontWeight: FontWeight.bold)))],), const SizedBox(height: 24), const Text("Description", style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold)), const SizedBox(height: 8), Text(property.description, style: const TextStyle(fontSize: 16, height: 1.5)), const SizedBox(height: 24), if (property.amenities.isNotEmpty) Column(crossAxisAlignment: CrossAxisAlignment.start, children: [const Text("Amenities", style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold)), const SizedBox(height: 8), Wrap(spacing: 8, runSpacing: 8, children: property.amenities.map((amenity) => Chip(label: Text(amenity), backgroundColor: Colors.blue.shade100)).toList())]), const SizedBox(height: 24), Row(children: [Expanded(child: ElevatedButton.icon(onPressed: () => _contactAgent(context, property), icon: const Icon(Icons.message), label: const Text("Contact Agent"), style: ElevatedButton.styleFrom(padding: const EdgeInsets.symmetric(vertical: 12)))), const SizedBox(width: 16), Expanded(child: OutlinedButton.icon(onPressed: () => _toggleFavorite(context, property), icon: const Icon(Icons.favorite_border), label: const Text("Favorite"), style: OutlinedButton.styleFrom(padding: const EdgeInsets.symmetric(vertical: 12))))]), const SizedBox(height: 24), Row(children: [Icon(Icons.visibility, color: Colors.grey), const SizedBox(width: 8), Text("\${property.views} views", style: const TextStyle(color: Colors.grey)), const SizedBox(width: 24), Icon(Icons.favorite, color: Colors.grey), const SizedBox(width: 8), Text("\${property.favorites} favorites", style: const TextStyle(color: Colors.grey))],), const SizedBox(height: 16), Text("Listed on \${_formatDate(property.createdAt)}", style: const TextStyle(color: Colors.grey, fontSize: 12))])),)); } }); } Widget _buildInfoCard(String title, String value, IconData icon) { return Container(padding: const EdgeInsets.all(16), decoration: BoxDecoration(border: Border.all(color: Colors.grey.shade300), borderRadius: BorderRadius.circular(8)), child: Column(children: [Icon(icon, size: 32, color: Colors.blue), const SizedBox(height: 8), Text(value, style: const TextStyle(fontSize: 18, fontWeight: FontWeight.bold)), Text(title, style: const TextStyle(color: Colors.grey))])); } Future<Property> _loadProperty() async { // This would be replaced with actual API call // For now, returning a mock property return Property(id: id, title: "Sample Property", description: "This is a beautiful property with amazing amenities.", type: "House", status: "For Sale", price: 500000, bedrooms: 3, bathrooms: 2, area: 2000, address: "123 Main St", city: "New York", state: "NY", zipcode: "10001", images: [], amenities: ["Parking", "Garden", "Balcony"], createdAt: DateTime.now(), updatedAt: DateTime.now()); } void _contactAgent(BuildContext context, Property property) { showDialog(context: context, builder: (context) => AlertDialog(title: const Text("Contact Agent"), content: const Text("This feature will be implemented to contact the property agent."), actions: [TextButton